mapper.select:
SELECT id, conversation_id, role, content, metadata, created_at,
       generation_status, reply_to_message_id
FROM chat_message WHERE conversation_id = #{conversationId}
AND (generation_status IS NULL OR generation_status = 'COMPLETED')
ORDER BY id DESC LIMIT #{limit}

SELECT m.id, m.conversation_id, m.role, m.content, m.metadata, m.created_at
FROM chat_message m JOIN conversation c ON c.id=m.conversation_id
WHERE m.conversation_id=#{c}
  AND (m.generation_status IS NULL OR m.generation_status='COMPLETED')
  AND m.id > COALESCE(c.summarized_until_id, 0) AND m.id < #{cutoff}
ORDER BY m.id LIMIT 200

mapper.update:
UPDATE conversation SET summary = #{summary}, summarized_until_id = #{untilId},
                        updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND COALESCE(summarized_until_id, 0) < #{untilId}
